#include "MojuloHUD.h"

#include "Engine/Canvas.h"
#include "Engine/Engine.h"
#include "Engine/Font.h"
#include "MojuloGameMode.h"

void AMojuloHUD::DrawHUD()
{
    Super::DrawHUD();
    AMojuloGameMode* Mode = GetWorld() ? GetWorld()->GetAuthGameMode<AMojuloGameMode>() : nullptr;
    if (Mode == nullptr || Canvas == nullptr) return;
    UFont* Font = GEngine->GetLargeFont();

    TArray<FString> Parts;
    if (Mode->Hp >= 0.f) Parts.Add(FString::Printf(TEXT("HP %d"), FMath::CeilToInt(Mode->Hp)));
    if (Mode->SurviveLeft >= 0.f) Parts.Add(FString::Printf(TEXT("SURVIVE %d"), FMath::CeilToInt(Mode->SurviveLeft)));
    for (const TPair<FString, int32>& Item : Mode->Bag)
        Parts.Add(FString::Printf(TEXT("%s \u00d7%d"), *Item.Key.ToUpper(), Item.Value));
    if (Parts.Num() > 0)
        DrawText(FString::Join(Parts, TEXT("   ")), FLinearColor::White, 16.f, 12.f, Font, 1.4f);

    if (!Mode->Banner.IsEmpty())
    {
        const FLinearColor Color = Mode->State == TEXT("failed") ? FLinearColor(1.f, 0.35f, 0.3f) : FLinearColor::White;
        const float Scale = 3.f;
        float W = 0.f, H = 0.f;
        GetTextSize(Mode->Banner, W, H, Font, Scale);
        DrawText(Mode->Banner, Color, (Canvas->SizeX - W) / 2.f, (Canvas->SizeY - H) / 2.f, Font, Scale);
    }
}
